begin;create table public.employee_financial_publications(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),payroll_cycle_id uuid not null references public.payroll_cycles(id),employment_link_id uuid not null references public.employment_links(id),document_type text not null,reference_month date not null,payload jsonb not null,document_sha256 text not null,verification_code text not null,published_at timestamptz default now(),revoked_at timestamptz,check(document_type in('contracheque','ficha_financeira','informe_rendimentos','extrato_ferias','margem_consignavel')),check(document_sha256~'^[0-9a-f]{64}$'),unique(payroll_cycle_id,employment_link_id,document_type));create index employee_financial_self_idx on public.employee_financial_publications(employment_link_id,reference_month desc)where revoked_at is null;alter table public.employee_financial_publications enable row level security;do $$begin if to_regnamespace('auth')is not null then create policy employee_financial_self on public.employee_financial_publications for select to authenticated using(exists(select 1 from public.employment_links l where l.id=employment_link_id and l.legacy_profile_id=auth.uid())or private.has_tenant_permission(tenant_id,'payroll.cycles.read'));end if;end$$;revoke all on public.employee_financial_publications from anon;do $$begin if exists(select 1 from pg_roles where rolname='authenticated')then grant select on public.employee_financial_publications to authenticated;end if;end$$;commit;
